// پل بین کامپوننت‌های Svelte و وضعیت برنامه (CourseRuntime، فیچرها، آیکن‌ها).
// همهٔ دسترسی‌ها به window اینجا جمع شده‌اند تا کامپوننت‌ها تمیز بمانند.
import { resolveLabel } from "../engine/presentation/labels";

interface RuntimeLike {
  getCourse(): { meta?: unknown; sessions?: unknown[] } | null;
  getActivePackId(): string;
  listPacks(): { id: string; title: string }[];
  activatePack(id: string): boolean;
}
interface AppWindow {
  CourseRuntime?: RuntimeLike;
  featureEnabled?: (name: string) => boolean;
  icon?: (name: string) => string;
}
const w = (): AppWindow => window as unknown as AppWindow;

export function featureOn(name: string): boolean {
  const fn = w().featureEnabled;
  return typeof fn === "function" ? !!fn(name) : true;
}

export function iconSvg(name: string): string {
  const fn = w().icon;
  return typeof fn === "function" ? fn(name) : "";
}

/** برچسب یک مسیر از پک (6.8)؛ کلید ناشناخته خودش را برمی‌گرداند. */
export function routeLabel(id: string): string {
  const course = w().CourseRuntime?.getCourse();
  return resolveLabel(
    course ? { labels: (course.meta as { labels?: unknown } | undefined)?.labels } : null,
    id,
  );
}

export function runtime(): RuntimeLike | undefined {
  return w().CourseRuntime;
}
