// «مرور بعدی» برای صفحهٔ اصلی (Phase 7.5). خالص؛ ورودی همان nextDueAt واحدهای mastery.

export interface DueCandidate {
  readonly id: string;
  readonly nextDueAt: number | null;
}

export interface NextReview {
  readonly id: string;
  readonly dueAt: number;
  /** true یعنی زمانِ مرور گذشته است. */
  readonly overdue: boolean;
}

/** زودترین واحد زمان‌بندی‌شده. واحدی بدون زمان یا فهرست خالی → null. */
export function nextReview(units: readonly DueCandidate[], now: number): NextReview | null {
  let best: DueCandidate | null = null;
  for (const u of units) {
    if (u.nextDueAt == null) continue;
    if (!best || u.nextDueAt < (best.nextDueAt as number)) best = u;
  }
  if (!best || best.nextDueAt == null) return null;
  return { id: best.id, dueAt: best.nextDueAt, overdue: best.nextDueAt <= now };
}
