// پاسخ‌های شروع (Phase 7.4). خالص: شکل رکورد، اعتبارسنجی، و نقشهٔ صفحهٔ شروع.
// این شکل موقت است تا ۱۰٫۳ برسد؛ رکورد نسخه‌دار است (version: 1) تا مهاجرت یک گام باشد.
// هیچ تاریخ تولد، پایه، یا نام پرسیده یا ذخیره نمی‌شود.

export type Who = "self" | "student" | "other";
export type Goal = "learn" | "review" | "exam";

export interface FirstRunAnswers {
  readonly who: Who | null;
  readonly course: string | null;
  readonly goal: Goal | null;
}

export interface FirstRunRecord {
  readonly version: 1;
  /** true بعد از پایان welcome؛ تا وقتی false است، welcome دوباره نشان داده می‌شود. */
  readonly welcomed: boolean;
  readonly answers: FirstRunAnswers;
  readonly updatedAt: number;
}

export const WHO_OPTIONS: readonly Who[] = ["self", "student", "other"];
export const GOAL_OPTIONS: readonly Goal[] = ["learn", "review", "exam"];

/** متن فارسی گزینه‌ها؛ هم پنجرهٔ شروع و هم بخش تنظیمات از همین‌جا می‌خوانند. */
export const WHO_LABEL: Record<Who, string> = {
  self: "خودآموز",
  student: "دانش‌آموز",
  other: "دیگر",
};
export const GOAL_LABEL: Record<Goal, string> = {
  learn: "یادگیری",
  review: "مرور",
  exam: "آمادگی برای امتحان",
};

export function emptyAnswers(): FirstRunAnswers {
  return { who: null, course: null, goal: null };
}

/** رکورد ذخیره‌شده را می‌خواند. شکل ناشناخته یا نسخهٔ دیگر → null (یعنی برای کاربر خوش‌آمد دوباره). */
export function parseRecord(raw: unknown): FirstRunRecord | null {
  if (!raw || typeof raw !== "object") return null;
  const r = raw as Record<string, unknown>;
  if (r.version !== 1 || typeof r.welcomed !== "boolean") return null;
  const a = (r.answers && typeof r.answers === "object" ? r.answers : {}) as Record<
    string,
    unknown
  >;
  return {
    version: 1,
    welcomed: r.welcomed,
    answers: {
      who: WHO_OPTIONS.includes(a.who as Who) ? (a.who as Who) : null,
      course: typeof a.course === "string" && a.course !== "" ? a.course : null,
      goal: GOAL_OPTIONS.includes(a.goal as Goal) ? (a.goal as Goal) : null,
    },
    updatedAt: typeof r.updatedAt === "number" ? r.updatedAt : 0,
  };
}

/** درس انتخاب‌شده فقط وقتی معتبر است که در پک‌های نصب‌شده باشد. */
export function sanitizeAnswers(a: FirstRunAnswers, packIds: readonly string[]): FirstRunAnswers {
  return { ...a, course: a.course && packIds.includes(a.course) ? a.course : null };
}

export interface HomePlan {
  /** مسیری که برنامه با آن باز می‌شود. */
  readonly landing: string;
  /** مسیرهای قابل‌نمایش در نوار تب و نوار کناری؛ null یعنی همه (بدون پاسخ). */
  readonly actions: readonly string[] | null;
}

const BY_GOAL: Record<Goal, { landing: string; actions: string[] }> = {
  learn: { landing: "home", actions: ["home", "library", "progress"] },
  review: { landing: "review", actions: ["home", "review", "progress", "library"] },
  exam: { landing: "exam", actions: ["home", "exam", "problems", "progress"] },
};

// کدام مسیر به کدام فیچر وابسته است؛ فیچر خاموش یعنی مسیر حذف می‌شود.
const FEATURE_OF: Record<string, string> = { review: "review", exam: "exam", problems: "problems" };

/**
 * نقشهٔ پاسخ‌ها به صفحهٔ شروع و فهرست اقدام‌ها.
 * - هدف: مسیر شروع و اقدام‌های اصلی.
 * - دانش‌آموز: تمرین‌ها همیشه در فهرست است.
 * - تنظیمات همیشه در دسترس است.
 * بدون هدف (همه پاسخ‌ها رد شده) → صفحهٔ اصلی و همهٔ اقدام‌ها.
 */
export function planFor(a: FirstRunAnswers, isFeatureOn: (name: string) => boolean): HomePlan {
  if (!a.goal) return { landing: "home", actions: null };
  const base = BY_GOAL[a.goal];
  const visible = (id: string) => {
    const f = FEATURE_OF[id];
    return !f || isFeatureOn(f);
  };
  const actions = base.actions.filter(visible);
  if (a.who === "student" && visible("problems") && !actions.includes("problems")) {
    actions.push("problems");
  }
  if (!actions.includes("settings")) actions.push("settings");
  const landing = visible(base.landing) ? base.landing : "home";
  return { landing, actions };
}
