(function () {
  "use strict";
  const N = 4;
  const COLORS = ["#3b82f6", "#f59e0b", "#10b981", "#ef4444"];
  const HOP_SEC = 0.9; // مدت یک عبور از در (ثانیه)
  const STEP_SEC = 1.1; // فاصلهٔ خودکار بین دو عبور

  function choose(n, k) {
    let r = 1;
    for (let i = 1; i <= k; i++) r = (r * (n - k + i)) / i;
    return Math.round(r);
  }
  const rnd = (a, b) => a + Math.random() * (b - a);

  function btn(label, attr) {
    return (
      '<button type="button" ' + attr +
      ' style="font:inherit;font-size:12px;padding:5px 12px;border-radius:999px;border:1px solid currentColor;background:transparent;color:inherit;cursor:pointer">' +
      label + "</button>"
    );
  }

  const W = {
    title: "شبیه‌ساز: چهار ذرهٔ متحرک",
    desc: "ذره‌ها در هر محفظه حرکت می‌کنند. با هر گام یک ذره از در می‌گذرد؛ هر حالت کلان که پدید آید شمرده می‌شود.",
    mount(box) {
      box.innerHTML =
        '<div style="font-family:inherit">' +
        '<canvas data-cv style="width:100%;height:200px;display:block;border-radius:12px;background:var(--surface-subtle)"></canvas>' +
        '<div style="display:flex;gap:8px;flex-wrap:wrap;margin:10px 0">' +
        btn("توقف", 'data-play') + btn("گام بعدی", 'data-step') + btn("در: باز", 'data-door') + btn("بازنشانی", 'data-reset') +
        "</div>" +
        '<div data-info style="font-size:13px;line-height:1.9"></div>' +
        '<div data-hist style="margin-top:8px;font-size:11px"></div>' +
        "</div>";

      const cv = box.querySelector("[data-cv]");
      const ctx = cv.getContext("2d");
      const infoEl = box.querySelector("[data-info]");
      const histEl = box.querySelector("[data-hist]");
      const btnPlay = box.querySelector("[data-play]");
      const btnStep = box.querySelector("[data-step]");
      const btnDoor = box.querySelector("[data-door]");
      const btnReset = box.querySelector("[data-reset]");

      const S = {
        running: true,
        doorOpen: true,
        parts: [],
        hop: null,
        visits: [0, 0, 0, 0, 0],
        total: 0,
        stepT: 0,
        raf: 0,
        last: 0,
        dirty: true,
      };

      function fresh() {
        S.parts = [];
        for (let i = 0; i < N; i++) {
          S.parts.push({
            box: i < 2 ? 0 : 1,
            x: rnd(0.2, 0.8),
            y: rnd(0.2, 0.8),
            vx: rnd(-0.3, 0.3),
            vy: rnd(-0.3, 0.3),
          });
        }
        S.hop = null;
        S.visits = [0, 0, 0, 0, 0];
        S.total = 0;
        S.dirty = true;
      }

      function nLeft() {
        return S.parts.filter((p) => p.box === 0).length;
      }

      function recordState() {
        S.visits[nLeft()]++;
        S.total++;
        S.dirty = true;
      }

      // مختصات ذره روی بوم: هر محفظه نیمی از عرض، با حاشیه
      function geom() {
        const w = cv.width, h = cv.height;
        const bw = w * 0.4, bh = h * 0.72;
        const top = h * 0.14;
        return {
          w, h, bw, bh, top,
          x0: [w * 0.04, w * 0.56],
        };
      }
      function toGlobal(g, boxIdx, x, y) {
        return { X: g.x0[boxIdx] + x * g.bw, Y: g.top + y * g.bh };
      }

      function startHop() {
        if (S.hop || !S.doorOpen) return false;
        const i = Math.floor(Math.random() * N);
        const p = S.parts[i];
        const target = 1 - p.box;
        const g = geom();
        const from = toGlobal(g, p.box, p.x, p.y);
        const tx = rnd(0.2, 0.8), ty = rnd(0.2, 0.8);
        const to = toGlobal(g, target, tx, ty);
        S.hop = { i, target, tx, ty, from, to, t: 0 };
        return true;
      }

      function finishHop() {
        const h = S.hop;
        const p = S.parts[h.i];
        p.box = h.target;
        p.x = h.tx;
        p.y = h.ty;
        S.hop = null;
        recordState();
      }

      function step() {
        if (S.hop) return;
        if (S.doorOpen) {
          startHop();
        } else {
          recordState();
        }
      }

      function jiggle(dt) {
        S.parts.forEach((p, i) => {
          if (S.hop && S.hop.i === i) return;
          p.vx += rnd(-1, 1) * 0.9 * dt;
          p.vy += rnd(-1, 1) * 0.9 * dt;
          const sp = Math.hypot(p.vx, p.vy);
          if (sp > 0.45) {
            p.vx *= 0.45 / sp;
            p.vy *= 0.45 / sp;
          }
          p.x += p.vx * dt;
          p.y += p.vy * dt;
          if (p.x < 0.1) { p.x = 0.1; p.vx = Math.abs(p.vx); }
          if (p.x > 0.9) { p.x = 0.9; p.vx = -Math.abs(p.vx); }
          if (p.y < 0.1) { p.y = 0.1; p.vy = Math.abs(p.vy); }
          if (p.y > 0.9) { p.y = 0.9; p.vy = -Math.abs(p.vy); }
        });
      }

      function draw() {
        const dpr = window.devicePixelRatio || 1;
        const rect = cv.getBoundingClientRect();
        if (!rect.width) return;
        const cw = Math.round(rect.width * dpr), ch = Math.round(rect.height * dpr);
        if (cv.width !== cw || cv.height !== ch) {
          cv.width = cw;
          cv.height = ch;
          S.dirty = true;
        }
        const g = geom();
        ctx.clearRect(0, 0, g.w, g.h);
        ctx.lineWidth = 2 * dpr;
        ctx.strokeStyle = getComputedStyle(cv).color || "#888";
        // دو محفظه
        [0, 1].forEach((b) => {
          ctx.globalAlpha = 0.55;
          ctx.strokeRect(g.x0[b], g.top, g.bw, g.bh);
        });
        ctx.globalAlpha = 1;
        // دیوار میانی با در
        const mx = g.x0[0] + g.bw + (g.x0[1] - g.x0[0] - g.bw) / 2;
        ctx.beginPath();
        if (S.doorOpen) {
          ctx.setLineDash([6 * dpr, 6 * dpr]);
          ctx.moveTo(mx, g.top);
          ctx.lineTo(mx, g.top + g.bh);
        } else {
          ctx.moveTo(mx, g.top);
          ctx.lineTo(mx, g.top + g.bh);
        }
        ctx.stroke();
        ctx.setLineDash([]);
        // ذره‌ها
        const r = Math.max(6 * dpr, g.h * 0.04); // ذره‌ها کوچک‌تر
        S.parts.forEach((p, i) => {
          let X, Y;
          if (S.hop && S.hop.i === i) {
            const t = S.hop.t;
            const e = t * t * (3 - 2 * t);
            X = S.hop.from.X + (S.hop.to.X - S.hop.from.X) * e;
            Y = S.hop.from.Y + (S.hop.to.Y - S.hop.from.Y) * e - g.h * 0.22 * Math.sin(Math.PI * t);
          } else {
            const q = toGlobal(g, p.box, p.x, p.y);
            X = q.X;
            Y = q.Y;
          }
          ctx.beginPath();
          ctx.fillStyle = COLORS[i];
          ctx.arc(X, Y, r, 0, Math.PI * 2);
          ctx.fill();
          ctx.fillStyle = "#fff";
          ctx.font = "bold " + Math.round(r * 1.05) + "px system-ui, sans-serif";
          ctx.textAlign = "center";
          ctx.textBaseline = "middle";
          ctx.fillText(String(i + 1), X, Y);
        });
        // برچسب محفظه‌ها
        ctx.fillStyle = getComputedStyle(cv).color || "#888";
        ctx.globalAlpha = 0.6;
        ctx.font = Math.round(11 * dpr) + "px system-ui, sans-serif";
        ctx.textAlign = "center";
        ctx.fillText("چپ", g.x0[0] + g.bw / 2, g.top + g.bh + 14 * dpr);
        ctx.fillText("راست", g.x0[1] + g.bw / 2, g.top + g.bh + 14 * dpr);
        ctx.globalAlpha = 1;
      }

      function updateText() {
        if (!S.dirty) return;
        S.dirty = false;
        const n = nLeft();
        const om = choose(N, n);
        const pr = (om / 16) * 100;
        infoEl.innerHTML =
          "<div>حالت کلان: <b>" + n + "</b> ذره در چپ · Ω = C(4, " + n + ") = <b>" + om + "</b></div>" +
          "<div>P = " + om + "/16 = <b>" + pr.toFixed(1) + "%</b> · S/k_B = ln Ω = <b>" + Math.log(om).toFixed(2) + "</b></div>" +
          "<div style=\"opacity:.65\">حالت‌های شمرده‌شده: " + S.total + "</div>";
        let rows = "";
        for (let k = 0; k <= N; k++) {
          const obs = S.total ? (S.visits[k] / S.total) * 100 : 0;
          const th = (choose(N, k) / 16) * 100;
          rows +=
            '<div style="display:grid;grid-template-columns:24px 1fr 44px;align-items:center;gap:6px;margin:2px 0">' +
            "<span>" + k + "</span>" +
            '<div style="position:relative;height:8px;border-radius:99px;background:var(--surface-subtle)">' +
            '<i style="position:absolute;inset-inline-start:0;top:0;bottom:0;width:' + Math.min(100, obs).toFixed(1) + '%;border-radius:99px;background:var(--accent);transition:width .3s"></i>' +
            '<i style="position:absolute;top:-3px;bottom:-3px;width:2px;background:currentColor;opacity:.55;inset-inline-start:' + th.toFixed(1) + '%"></i>' +
            "</div>" +
            '<span dir="ltr" style="text-align:end">' + obs.toFixed(0) + "%</span></div>";
        }
        histEl.innerHTML =
          '<div style="opacity:.65;margin-bottom:4px">فراوانی مشاهده‌شده (نوار رنگی) در برابر احتمال نظری (خط)</div>' + rows;
      }

      function loop(now) {
        const dt = S.last ? Math.min(0.05, (now - S.last) / 1000) : 0;
        S.last = now;
        if (S.running) {
          S.stepT += dt;
          if (S.stepT >= STEP_SEC && !S.hop) {
            S.stepT = 0;
            step();
          }
        }
        if (S.hop) {
          S.hop.t += dt / HOP_SEC;
          if (S.hop.t >= 1) finishHop();
        }
        jiggle(dt);
        draw();
        updateText();
        S.raf = requestAnimationFrame(loop);
      }

      function setPlay() {
        btnPlay.textContent = S.running ? "توقف" : "ادامه";
      }
      function setDoor() {
        btnDoor.textContent = S.doorOpen ? "در: باز" : "در: بسته";
      }

      btnPlay.onclick = () => { S.running = !S.running; setPlay(); };
      btnStep.onclick = () => { if (!S.hop) step(); };
      btnDoor.onclick = () => { S.doorOpen = !S.doorOpen; setDoor(); S.dirty = true; };
      btnReset.onclick = () => { fresh(); };

      fresh();
      setPlay();
      setDoor();
      S.raf = requestAnimationFrame(loop);
      box._lzMicro = S;
    },
    unmount(box) {
      const S = box._lzMicro;
      if (S) cancelAnimationFrame(S.raf);
      box._lzMicro = null;
      box.innerHTML = "";
    },
  };

  CourseRuntime.registerPackSource("entropy-metaphor", { widgets: { microstates: W } });
})();
