<script lang="ts">
  // «مرور بعدی» در صفحهٔ اصلی (Phase 7.5): واحد جلسه‌ای که زودتر باید مرور شود.
  import { onMount } from "svelte";
  import { nextReview, type NextReview } from "./next-review";

  let result = $state<NextReview | null>(null);
  let label = $state("");
  let loaded = $state(false);

  onMount(async () => {
    try {
      const view = await window.LearningState!.masteryReport();
      const units = view.report.units;
      result = nextReview(units, view.report.now);
      if (result) label = units.find((u) => u.id === result!.id)?.label ?? result.id;
    } catch {
      result = null;
    } finally {
      loaded = true;
    }
  });

  const when = (ms: number) =>
    new Date(ms).toLocaleString("fa-IR", { dateStyle: "medium", timeStyle: "short" });

  // «در ۳ ساعت» به جای تاریخ خام؛ اگر Intl نبود، تاریخ کامل.
  const relative = (ms: number): string => {
    const mins = Math.max(1, Math.round((ms - Date.now()) / 60000));
    try {
      const rtf = new Intl.RelativeTimeFormat("fa", { numeric: "auto" });
      if (mins < 60) return rtf.format(mins, "minute");
      if (mins < 1440) return rtf.format(Math.round(mins / 60), "hour");
      return rtf.format(Math.round(mins / 1440), "day");
    } catch {
      return when(ms);
    }
  };
</script>

{#if loaded && result}
  <section class="lt-next" aria-label="مرور بعدی">
    <div class="lt-next-top">
      <span class="lt-eyebrow">مرور بعدی</span>
      <span class="lt-chip" class:due={result.overdue}>
        {result.overdue ? "وقت مرور است" : relative(result.dueAt)}
      </span>
    </div>
    <p class="lt-next-title">{label}</p>
    <p class="lt-next-sub">
      {result.overdue ? "این واحد را همین حالا مرور کن تا مطالبش در ذهنت بماند." : "زمان‌بندی بر اساس پاسخ‌های تو تنظیم شده است."}
    </p>
  </section>
{/if}
