<script lang="ts">
  // نوار تب پایین گوشی (Phase 7.1). مسیرها از routes.ts می‌آیند؛ برچسب‌ها از پک.
  import { onMount } from "svelte";
  import { resolveRoute, tabRoutes } from "./routes";
  import { routeLabel, featureOn, iconSvg } from "../mount-helpers";
  import { planState } from "../../first-run/plan-state.svelte";

  let hash = $state(typeof location !== "undefined" ? location.hash : "");
  const current = $derived(resolveRoute(hash).id);
  // نوار تب فقط مسیرهای نقشهٔ شروع را نشان می‌دهد؛ بدون پاسخ همه نمایش داده می‌شوند.
  // دوک فقط مقصدهای اصلی را دارد؛ تنظیمات و بقیهٔ مسیرها از «بیشتر» (همان فهرست کناری) باز می‌شوند.
  const tabs = $derived(
    tabRoutes(featureOn).filter(
      (t) => t.id !== "settings" && (!planState.actions || planState.actions.includes(t.id)),
    ),
  );
  // روی گوشی تنها یک سطح ناوبری هست: دوک. دکمهٔ منوی هدر پنهان است و «بیشتر» همان فهرست را باز می‌کند.
  function openMenu() {
    document.getElementById("navToggle")?.click();
  }

  onMount(() => {
    const onHash = () => (hash = location.hash);
    window.addEventListener("hashchange", onHash);
    return () => window.removeEventListener("hashchange", onHash);
  });

  const ICON: Record<string, string> = {
    home: "home",
    library: "library",
    progress: "target",
    review: "cards",
    settings: "sliders",
  };
</script>

<nav class="lv-tabs" aria-label="ناوبری اصلی">
  {#each tabs as tab (tab.id)}
    <a
      class="lv-tab"
      href={"#/" + tab.id}
      aria-current={current === tab.id ? "page" : undefined}
    >
      <span class="lv-ico" aria-hidden="true">{@html iconSvg(ICON[tab.id] ?? "home")}</span>
      <span class="lv-tx">{routeLabel(tab.id)}</span>
    </a>
  {/each}
  <button class="lv-tab lv-more" type="button" aria-label="بیشتر" onclick={openMenu}>
    <span class="lv-ico" aria-hidden="true">{@html iconSvg("more")}</span>
    <span class="lv-tx">بیشتر</span>
  </button>
</nav>

