// ذخیرهٔ موقت پاسخ‌های شروع در IndexedDB (Phase 7.4). با ۱۰٫۶ جایگزین می‌شود.
// پایگاه داده جدا از lector-learning است تا نسخه‌ها با هم تداخل نکنند.
import { parseRecord, type FirstRunRecord } from "./model";

const DB_NAME = "lector-first-run";
const STORE = "kv";
const KEY = "firstRun";

function openDb(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    if (typeof indexedDB === "undefined" || !indexedDB) {
      reject(new Error("indexedDB unavailable"));
      return;
    }
    const req = indexedDB.open(DB_NAME, 1);
    req.onupgradeneeded = () => {
      if (!req.result.objectStoreNames.contains(STORE)) req.result.createObjectStore(STORE);
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
    req.onblocked = () => reject(new Error("indexedDB blocked"));
  });
}

/** رکورد ذخیره‌شده؛ هر خطایی (نبود IndexedDB، پاک‌شدن داده، شکل نامعتبر) → null یعنی خوش‌آمد دوباره. */
export async function loadFirstRun(): Promise<FirstRunRecord | null> {
  try {
    const db = await openDb();
    return await new Promise<FirstRunRecord | null>((resolve, reject) => {
      const req = db.transaction(STORE, "readonly").objectStore(STORE).get(KEY);
      req.onsuccess = () => {
        db.close();
        resolve(parseRecord(req.result));
      };
      req.onerror = () => {
        db.close();
        reject(req.error);
      };
    });
  } catch {
    return null;
  }
}

/** true یعنی ذخیره شد. false یعنی ذخیره نشد (در این حالت دفعهٔ بعد دوباره پرسیده می‌شود). */
export async function saveFirstRun(rec: FirstRunRecord): Promise<boolean> {
  try {
    const db = await openDb();
    return await new Promise<boolean>((resolve) => {
      const tx = db.transaction(STORE, "readwrite");
      tx.objectStore(STORE).put(rec, KEY);
      tx.oncomplete = () => {
        db.close();
        resolve(true);
      };
      tx.onerror = () => {
        db.close();
        resolve(false);
      };
      tx.onabort = () => {
        db.close();
        resolve(false);
      };
    });
  } catch {
    return false;
  }
}
