import { getPref } from "./prefs.js";

// چهار پوسته: پیش‌فرض، کنتراست بالا، مینیمال، کهکشانی.
// «accent» در allowed یعنی پالت رنگ فعال است؛ مینیمال عمداً بدون پالت است.
// شناسهٔ «academic» برای سازگاری با تنظیمات ذخیره‌شده نگه داشته شده و برچسبش «پیش‌فرض» است.
export type ThemeId = "academic" | "hicontrast" | "minimal" | "cosmic";

export interface ThemeAccent {
  dark: string;
  light: string;
}

/** پالت کارت پیش‌نمایش در تنظیمات؛ فقط برای نمایش است و تم واقعی همچنان از توکن‌های CSS می‌آید. */
export interface ThemeMock {
  bg: string;
  surface: string;
  text: string;
  muted: string;
  primary: string;
  /** حالت‌هایی که پوسته پشتیبانی می‌کند: ["light","dark"] یا ["dark"] */
  modes: Array<"light" | "dark">;
  /** شناسهٔ رنگ‌های تأکیدی که در نوار ۲۰٪ کارت نشان داده می‌شوند (خالی = بدون اکسنت) */
  accents: string[];
}

export interface ThemePreset {
  id: ThemeId;
  label: string;
  hint: string;
  tags: string[];
  allowed: string[];
  accent: ThemeAccent;
  mock: ThemeMock;
  preview: () => string;
}

export interface ThemeListItem {
  id: ThemeId;
  label: string;
  hint: string;
  tags: string[];
  accent: ThemeAccent;
  mock: ThemeMock;
  preview: string;
}

