// فهرست واحد مسیرها (Phase 7.2). هر مسیر یک شناسهٔ ثابت دارد.
// feature: اگر تنظیم شده باشد، مسیر فقط وقتی فعال است که فیچر پک روشن باشد.
// tab: در نوار تب گوشی نمایش داده می‌شود.

export interface RouteDef {
  readonly id: string;
  readonly feature?: string;
  readonly tab?: boolean;
}

export const ROUTES: readonly RouteDef[] = Object.freeze([
  { id: "home", tab: true },
  { id: "library", tab: true },
  { id: "plan" },
  { id: "shop", feature: "shop" },
  { id: "progress", tab: true },
  { id: "review", feature: "review", tab: true },
  { id: "problems", feature: "problems" },
  { id: "exam", feature: "exam" },
  { id: "lab", feature: "labs" },
  { id: "graph", feature: "graph" },
  { id: "glossary", feature: "glossary" },
  { id: "refs", feature: "refs" },
  { id: "guide" },
  { id: "settings", tab: true },
  // مسیرهای با پارامتر: #/p/<pack>/s/<session> و #/p/<pack>
  { id: "session" },
  { id: "pack" },
]);

export const DEFAULT_ROUTE = "home";

export interface ResolvedRoute {
  /** شناسهٔ مسیر؛ برای مسیر ناشناخته همیشه DEFAULT_ROUTE. */
  readonly id: string;
  /** false یعنی مسیر در فهرست نیست و به داشبورد برگشته شد. */
  readonly known: boolean;
  readonly packId: string | null;
  readonly sessionId: string | null;
}

const KNOWN = new Set(ROUTES.map((r) => r.id));

/** هش را به مسیر تبدیل می‌کند. ناشناخته → داشبورد. */
export function resolveRoute(hash: string): ResolvedRoute {
  const h = (hash || "").replace(/^#\/?/, "");
  const parts = h
    .split("/")
    .filter(Boolean)
    .map((p) => {
      try {
        return decodeURIComponent(p);
      } catch {
        return p;
      }
    });
  const fallback: ResolvedRoute = {
    id: DEFAULT_ROUTE,
    known: false,
    packId: null,
    sessionId: null,
  };
  if (parts.length === 0) return { ...fallback, known: true };

  if (parts[0] === "p" && parts[1]) {
    if (parts[2] === "s" && parts[3]) {
      return { id: "session", known: true, packId: parts[1], sessionId: parts[3] };
    }
    if (parts.length === 2) return { id: "pack", known: true, packId: parts[1], sessionId: null };
    return fallback;
  }

  const first = parts[0] ?? "";
  if (parts.length === 1 && KNOWN.has(first)) {
    return { id: first, known: true, packId: null, sessionId: null };
  }
  return fallback;
}

/** مسیر برای تب‌های گوشی: فقط مسیرهایی که tab=true دارند و فیچرشان روشن است. */
export function tabRoutes(isFeatureOn: (name: string) => boolean): RouteDef[] {
  return ROUTES.filter((r) => r.tab && (!r.feature || isFeatureOn(r.feature)));
}
