(function () {
  "use strict";
  // آب مایع: ΔH° = −571.6 kJ و ΔS° = −326.7 J/K؛ ΔH و ΔS ثابت فرض شده‌اند
  const DH = -571.6;
  const DS = -0.3267; // kJ/K
  const TMIN = 200;
  const TMAX = 2400;
  const dG = (T) => DH - T * DS;

  const W = {
    title: "ΔG = ΔH − TΔS برای تشکیل آب",
    desc: "دما را تغییر بده. علامت ΔG، نه ΔS، تعیین می‌کند که واکنش خودبه‌خودی است یا نه.",
    mount(box) {
      box.innerHTML =
        '<div style="font-family:inherit">' +
        '<label style="display:block;font-size:13px">دما: <strong data-T>298</strong> K' +
        '<input type="range" min="' + TMIN + '" max="' + TMAX + '" step="10" value="298" data-r style="width:100%;margin-top:6px"></label>' +
        '<div data-g style="font-size:30px;font-weight:700;margin:12px 0 4px;font-variant-numeric:tabular-nums"></div>' +
        '<div data-msg style="font-size:13px;line-height:1.8"></div>' +
        '<div style="position:relative;height:12px;margin-top:14px;border-radius:99px;background:var(--surface-subtle)">' +
        '<i data-mk style="position:absolute;top:-4px;width:20px;height:20px;margin-inline-start:-10px;border-radius:50%;background:var(--surface-raised);border:3px solid var(--accent)"></i></div>' +
        '<div style="font-size:11px;opacity:.6;margin-top:10px">تقاطع تقریبی ΔG = 0 حدود ۱۷۵۰ K است. بالای نقطهٔ جوش آب، این مدل معتبر نیست، پس عدد فقط منطق را نشان می‌دهد.</div>' +
        "</div>";

      const slider = box.querySelector("[data-r]");
      const tOut = box.querySelector("[data-T]");
      const gOut = box.querySelector("[data-g]");
      const msg = box.querySelector("[data-msg]");
      const mk = box.querySelector("[data-mk]");

      function render() {
        const T = Number(slider.value);
        const g = dG(T);
        tOut.textContent = String(T);
        gOut.textContent = "ΔG ≈ " + (g >= 0 ? "+" : "") + g.toFixed(1) + " kJ";
        gOut.style.color = g < 0 ? "var(--accent)" : "var(--text-primary)";
        msg.textContent =
          g < 0
            ? "ΔG < 0: واکنش در این دما خودبه‌خودی است، با وجود ΔS منفی."
            : "ΔG > 0: واکنش در این دما خودبه‌خودی نیست.";
        mk.style.insetInlineStart = ((T - TMIN) / (TMAX - TMIN)) * 100 + "%";
      }
      slider.addEventListener("input", render);
      render();
    },
    unmount(box) {
      box.innerHTML = "";
    },
  };

  CourseRuntime.registerPackSource("entropy-metaphor", { widgets: { "gibbs-slider": W } });
})();
