<script lang="ts">
  // دیالوگ تأیید واحد برای همهٔ برنامه (Phase 7.7). <dialog> بومی، Esc، و فوکوس داخل دیالوگ.
  import { onMount } from "svelte";

  let {
    title,
    message,
    confirmLabel,
    cancelLabel,
    onresult,
  }: {
    title: string;
    message: string;
    confirmLabel: string;
    cancelLabel: string;
    onresult: (ok: boolean) => void;
  } = $props();

  let dlg: HTMLDialogElement | undefined = $state();
  let done = false;

  function finish(ok: boolean) {
    if (done) return;
    done = true;
    onresult(ok);
  }

  onMount(() => {
    dlg?.showModal();
    // فوکوس روی دکمهٔ انصراف: تأیید تصادفی با Enter اتفاق نمی‌افتد.
    (dlg?.querySelector<HTMLButtonElement>("[data-cancel]"))?.focus();
  });
</script>

<dialog bind:this={dlg} class="dlg" aria-labelledby="dlg-title" oncancel={(e) => { e.preventDefault(); finish(false); }}>
  <h2 id="dlg-title" class="dlg-title">{title}</h2>
  <p class="dlg-msg">{message}</p>
  <div class="dlg-actions">
    <button type="button" class="btn" data-cancel onclick={() => finish(false)}>{cancelLabel}</button>
    <button type="button" class="btn primary" onclick={() => finish(true)}>{confirmLabel}</button>
  </div>
</dialog>

