// حالت‌های مطالعه (Phase 6.5): brief، detail، review. هر حالت یک تابع خالص است که
// چیدمان بدنه را توصیف می‌کند؛ DOM را لمس نمی‌کند (کار DOM با swap.ts است).
export const MODES = ["brief", "detail", "review"] as const;
export type Mode = (typeof MODES)[number];

export interface ModeContext {
  /** آیا جلسه بخش «مفصل» دارد. */
  hasDetail: boolean;
  /** آیا جلسه از مرور خارج شده (review: "off"). */
  reviewOff?: boolean;
}

export interface ModeView {
  id: Mode;
  /** بدنهٔ متن مفصل نمایش داده شود. */
  showDetailBody: boolean;
  /** فرمول‌ها در بدنه ظاهر شوند. */
  showFormulas: boolean;
  /** کارت‌های مرور (مفهوم و فلش‌کارت) نمایش داده شوند. */
  showCards: boolean;
}

type ModeFactory = (ctx: ModeContext) => ModeView;

export const MODE_VIEWS: Readonly<Record<Mode, ModeFactory>> = Object.freeze<
  Record<Mode, ModeFactory>
>({
  brief: () => ({ id: "brief", showDetailBody: false, showFormulas: true, showCards: false }),
  detail: () => ({ id: "detail", showDetailBody: true, showFormulas: false, showCards: false }),
  review: (ctx) => ({
    id: "review",
    showDetailBody: false,
    showFormulas: true,
    showCards: ctx.reviewOff !== true,
  }),
});

export function isMode(value: unknown): value is Mode {
  return typeof value === "string" && (MODES as readonly string[]).includes(value);
}

/**
 * حالت معتبر را برمی‌گرداند. «مفصل» بدون متن مفصل به «مختصر» تنزل می‌کند؛
 * هر مقدار ناشناخته هم «مختصر» است (همان پیش‌فرض session.js).
 */
export function resolveMode(value: unknown, ctx: ModeContext): Mode {
  if (!isMode(value)) return "brief";
  if (value === "detail" && !ctx.hasDetail) return "brief";
  return value;
}

export function modeView(value: unknown, ctx: ModeContext): ModeView {
  const id = resolveMode(value, ctx);
  return MODE_VIEWS[id](ctx);
}
