// نقطهٔ ورود Svelte در برنامه (Phase 7). کامپوننت‌ها را به جاهای شِل قدیمی وصل می‌کند.
// اجزای Svelte فقط در همین فایل mount می‌شوند؛ بقیهٔ کد همچنان از shell.js می‌آید.
import { mount, unmount } from "svelte";
import { haptic, initFeel } from "./feel/feel";
import { unitName } from "../engine/presentation/labels";
import LayoutSwitch from "./layout/LayoutSwitch.svelte";
import CourseTree from "./layout/CourseTree.svelte";
import NextReview from "./pages/home/NextReview.svelte";
import Dialog from "./components/Dialog.svelte";
import FirstRun from "./first-run/FirstRun.svelte";
import { runtime, featureOn } from "./mount-helpers";
import { resolveRoute } from "./layout/routes";
import type { TreeCourse } from "./layout/course-tree";
import {
  GOAL_LABEL,
  WHO_LABEL,
  emptyAnswers,
  planFor,
  sanitizeAnswers,
  type FirstRunAnswers,
} from "../first-run/model";
import { loadFirstRun, saveFirstRun } from "../first-run/store";
import { planState } from "../first-run/plan-state.svelte";

type Instance = ReturnType<typeof mount>;
let treeInstance: Instance | null = null;
let reviewInstance: Instance | null = null;
let wizardInstance: Instance | null = null;
let currentAnswers: FirstRunAnswers = emptyAnswers();

function safeUnmount(inst: Instance | null): void {
  if (!inst) return;
  try {
    void unmount(inst);
  } catch {
    // نود قبلاً از DOM برداشته شده؛ نیازی به خطا نیست.
  }
}

function packList(): { id: string; title: string }[] {
  return runtime()?.listPacks() ?? [];
}
function packIds(): string[] {
  return packList().map((p) => p.id);
}

/** درخت دوره‌ها از وضعیت فعلی: همهٔ پک‌ها؛ واحدهای دوره‌ی فعال (نام واحد از 6.9). */
function buildCourses(): TreeCourse[] {
  const rt = runtime();
  if (!rt) return [];
  const active = rt.getActivePackId();
  const course = rt.getCourse();
  const name = unitName(
    course ? { labels: (course.meta as { labels?: unknown } | undefined)?.labels } : null,
  );
  const sessions = (course?.sessions ?? []) as { id: string; num?: number; title?: string }[];
  return packList().map((p) => {
    const isActive = p.id === active;
    return {
      id: p.id,
      title: p.title,
      active: isActive,
      unitWord: name.plural,
      units: isActive
        ? sessions.map((s) => ({
            id: p.id + "/" + s.id,
            sessionId: s.id,
            label: [name.singular, s.num ?? "", s.title ? "· " + s.title : ""]
              .filter((x) => x !== "")
              .join(" "),
          }))
        : [],
    };
  });
}

/** درخت دوره‌ها را داخل نوار کناری mount می‌کند. هر بار که shell نوار را می‌سازد صدا زده می‌شود. */
export function mountCourseTree(scope: ParentNode | null = document): void {
  safeUnmount(treeInstance);
  treeInstance = null;
  const target = scope?.querySelector<HTMLElement>('[data-svelte="course-tree"]');
  if (!target) return;
  treeInstance = mount(CourseTree, { target, props: { courses: buildCourses() } });
}

/** آیتم‌های نوار کناری که در نقشهٔ شروع نیستند پنهان می‌شوند. */
function applySidebarVisibility(): void {
  const actions = planState.actions;
  document.querySelectorAll<HTMLElement>(".sb-item[data-route]").forEach((el) => {
    const id = el.dataset.route ?? "";
    el.style.display = actions && !actions.includes(id) ? "none" : "";
  });
}

/** «مرور بعدی» فقط در صفحهٔ اصلی. */
function mountHomeWidgets(): void {
  safeUnmount(reviewInstance);
  reviewInstance = null;
  if (resolveRoute(location.hash).id !== "home") return;
  const page = document.querySelector<HTMLElement>("#main .page");
  if (!page) return;
  const host = document.createElement("div");
  host.dataset.svelte = "next-review";
  page.prepend(host);
  reviewInstance = mount(NextReview, { target: host });
}

/** دیالوگ تأیید: Promise که با انتخاب کاربر resolve می‌شود. */
export function confirmDialog(opts: {
  title: string;
  message: string;
  confirmLabel?: string;
  cancelLabel?: string;
}): Promise<boolean> {
  return new Promise((resolve) => {
    const host = document.createElement("div");
    document.body.appendChild(host);
    let inst: Instance | null = null;
    const done = (ok: boolean) => {
      resolve(ok);
      queueMicrotask(() => {
        safeUnmount(inst);
        host.remove();
      });
    };
    inst = mount(Dialog, {
      target: host,
      props: {
        title: opts.title,
        message: opts.message,
        confirmLabel: opts.confirmLabel ?? "تأیید",
        cancelLabel: opts.cancelLabel ?? "انصراف",
        onresult: done,
      },
    });
  });
}

// ── پاسخ‌های شروع (7.4) ───────────────────────────────────────

/** نقشه را روی برنامه اعمال می‌کند: درس، فهرست اقدام‌ها و مسیر شروع. */
function applyAnswers(a: FirstRunAnswers, { route }: { route: boolean }): void {
  currentAnswers = a;
  const plan = planFor(a, featureOn);
  planState.actions = plan.actions;
  planState.landing = plan.landing;

  const rt = runtime();
  if (rt && a.course && a.course !== rt.getActivePackId()) {
    if (rt.activatePack(a.course)) {
      const g = window as unknown as Record<string, (() => void) | undefined>;
      g.applyPrefs?.();
      g.applyBrand?.();
      g.refreshShellSidebar?.();
    }
  }
  applySidebarVisibility();
  if (route) {
    const target = "#/" + plan.landing;
    if (location.hash === target) {
      (window as unknown as { route?: () => void }).route?.();
    } else {
      location.hash = target;
    }
  }
}

async function persist(answers: FirstRunAnswers): Promise<void> {
  const clean = sanitizeAnswers(answers, packIds());
  const ok = await saveFirstRun({
    version: 1,
    welcomed: true,
    answers: clean,
    updatedAt: Date.now(),
  });
  applyAnswers(clean, { route: true });
  if (!ok) {
    (window as unknown as { toast?: (m: string, k: string) => void }).toast?.(
      "ذخیرهٔ پاسخ‌ها انجام نشد؛ دفعهٔ بعد دوباره پرسیده می‌شود.",
      "warn",
    );
  }
}

function closeWizard(): void {
  safeUnmount(wizardInstance);
  wizardInstance = null;
}

function openWizard(mode: "first" | "edit", initial: FirstRunAnswers): void {
  closeWizard();
  const host = document.createElement("div");
  document.body.appendChild(host);
  wizardInstance = mount(FirstRun, {
    target: host,
    props: {
      mode,
      initial,
      packs: packList(),
      onfinish: async (a: FirstRunAnswers) => {
        haptic("success");
        closeWizard();
        host.remove();
        await persist(a);
      },
      oncancel: () => {
        closeWizard();
        host.remove();
      },
    },
  });
}

/** پاسخ‌های شروع در «پیشرفت مطالعه» تنظیمات: گروه، درس، هدف و دکمهٔ ویرایش. */
function firstRunAnswersHTML(): string {
  const a = currentAnswers;
  const course = packList().find((p) => p.id === a.course)?.title ?? null;
  const row = (k: string, v: string | null) =>
    `<div class="lt-path-row"><dt>${k}</dt><dd${v ? "" : ' class="none"'}>${v ?? "انتخاب نشده"}</dd></div>`;
  return `
    <div class="lt-path">
      <dl class="lt-path-list">
        ${row("گروه", a.who ? WHO_LABEL[a.who] : null)}
        ${row("درس", course)}
        ${row("هدف", a.goal ? GOAL_LABEL[a.goal] : null)}
      </dl>
      <div class="lt-path-actions">
        <button type="button" class="lt-btn" data-fr="edit">ویرایش پاسخ‌ها</button>
      </div>
    </div>`;
}

/** نمایش دوبارهٔ خوش‌آمد در «پیشرفته» تنظیمات. */
function firstRunResetHTML(): string {
  return `
    <div class="lt-path">
      <div class="lt-path-actions">
        <button type="button" class="lt-btn" data-fr="welcome">نمایش دوبارهٔ خوش‌آمد</button>
      </div>
    </div>`;
}

/** بوت اولیه: اگر خوش‌آمد دیده نشده، پنجره باز می‌شود؛ وگرنه نقشه اعمال می‌شود. */
async function startFirstRun(): Promise<void> {
  const h = location.hash;
  const atDefault = h === "" || h === "#" || h === "#/home";
  const rec = await loadFirstRun();
  if (!rec || !rec.welcomed) {
    // لینک مستقیم به یک صفحهٔ داخلی: خوش‌آمد نمایش داده نمی‌شود و ثبت هم نمی‌شود،
    // تا در ورود عادی بعدی همچنان نشان داده شود.
    if (!atDefault) return;
    currentAnswers = rec?.answers ?? emptyAnswers();
    openWizard("first", currentAnswers);
    return;
  }
  applyAnswers(rec.answers, { route: false });
  // فقط روی ورود عادی (بدون مسیر مشخص) به مسیر شروع می‌رویم؛ اگر کاربر صفحه‌ای را باز کرده، همان را نگه می‌داریم.
  if (atDefault && planState.landing && planState.landing !== "home") {
    location.hash = "#/" + planState.landing;
  }
}

/** یک بار در بوت: نوار تب گوشی، درخت دوره‌ها، مرور بعدی، شروع، و دیالوگ سراسری. */
export function mountChrome(): void {
  if (document.getElementById("lector-chrome")) return;
  initFeel();
  const host = document.createElement("div");
  host.id = "lector-chrome";
  document.querySelector(".app-sheet")?.appendChild(host);
  mount(LayoutSwitch, { target: host });

  mountCourseTree(document);
  mountHomeWidgets();
  window.addEventListener("hashchange", mountHomeWidgets);

  // دکمه‌های بخش «شروع» در تنظیمات (تفویض رویداد؛ بخش هر بار دوباره ساخته می‌شود).
  document.addEventListener("click", (e) => {
    const t = (e.target as HTMLElement | null)?.closest<HTMLButtonElement>("[data-fr]");
    if (!t) return;
    if (t.dataset.fr === "edit") openWizard("edit", currentAnswers);
    if (t.dataset.fr === "welcome") {
      // خوش‌آمد را دوباره نشان می‌دهد؛ پاسخ‌های قبلی حفظ می‌شوند.
      void saveFirstRun({
        version: 1,
        welcomed: false,
        answers: currentAnswers,
        updatedAt: Date.now(),
      });
      openWizard("first", currentAnswers);
    }
  });

  const g = window as unknown as Record<string, unknown>;
  g.mountSvelteParts = (root: ParentNode | null) => {
    mountCourseTree(root);
    applySidebarVisibility();
  };
  g.confirmDialog = confirmDialog;
  g.firstRunAnswersHTML = firstRunAnswersHTML;
  g.firstRunResetHTML = firstRunResetHTML;

  void startFirstRun();
}
