import { ArchetypeRegistry } from "./registry.js";
import type { ArchetypeSession } from "./registry.js";
import { resolveMode } from "../engine/presentation/modes.js";

// آرکی‌تایپ پایه (Phase 6.2): حالت‌ها brief، detail، review هستند (همان‌هایی که session.js رندر می‌کند).
// «مفصل» بدون بخش مفصل به «مختصر» تنزل می‌کند.
export function hasDetailSections(session: ArchetypeSession | undefined): boolean {
  return !!(session && session.detail && session.detail.sections && session.detail.sections.length);
}

ArchetypeRegistry.register({
  id: "base",
  version: 1,
  resolveMode(mode: string | undefined, session: ArchetypeSession | undefined): string {
    return resolveMode(mode, { hasDetail: hasDetailSections(session) });
  },
});
